#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

constexpr int64 MOD = 1000000007;

int64 modPow(int64 base, int64 exp) {
    base %= MOD;
    int64 result = 1;

    while (exp > 0) {
        if (exp & 1) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, k;
    cin >> n >> k;

    int64 valid = (k == 0 ? 1 : modPow(k, k - 1));
    int64 remaining = modPow(n - k, n - k);

    cout << valid * remaining % MOD;
    return 0;
}

