#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

constexpr int64 MOD = 1000000007;

int64 modPow(int64 base, int64 exponent) {
    base %= MOD;
    int64 result = 1;

    while (exponent > 0) {
        if (exponent & 1) result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, k;
    cin >> n >> k;

    int64 total = 1;

    if (k > 0) {
        total = 0;
        int64 fallingFactorial = 1;

        for (int64 cycleSize = 1; cycleSize < k; ++cycleSize) {
            int64 term = cycleSize % MOD;
            term = term * fallingFactorial % MOD;
            term = term * modPow(k, k - cycleSize - 1) % MOD;
            total = (total + term) % MOD;

            fallingFactorial =
                fallingFactorial * ((k - cycleSize) % MOD) % MOD;
        }

        total = (total + fallingFactorial) % MOD;
    }

    total = total * modPow(n - k, n - k) % MOD;
    cout << total;

    return 0;
}

