    int64 result = 1;
    while (exp > 0) {
        if (exp & 1) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, k;
    cin >> n >> k;

    int64 validMappings = (k <= 2) ? 1 : modPow(k, k - 2);
    int64 answer = validMappings * modPow(n - k, n - k) % MOD;

    cout << answer;
    return 0;
}

